import React from "react";
import { palette } from "../theme/palette";
import { Flower, GarlandSwag, Leaf, MarigoldStrand } from "../props/Florals";
import { FlowerHeap, Thali } from "../props/WeddingDayDecor";
import { Diya } from "../props/Ganesh";

/*
 * Lunch set: a garden with soft trees, a floral pergola canopy, and a long banquet table in
 * one-point perspective (thalis, floral runner, candle diyas) with a pleated front skirt that
 * carries the title. Scene space.
 */

export const GardenTrees: React.FC<{ y: number; fill: string; fill2: string }> = ({ y, fill, fill2 }) => (
  <g>
    {[
      [-40, 200, 1.1],
      [150, 160, 0.9],
      [330, 190, 1],
      [760, 180, 1.05],
      [930, 210, 1.1],
      [1100, 170, 0.9],
    ].map(([x, h, s], i) => (
      <g key={i} transform={`translate(${x} ${y}) scale(${s})`}>
        <rect x={-6} y={-40} width={12} height={60} fill="#8B6C4E" opacity={0.6} />
        <path d={`M-90 0 C-110 -60 -80 ${-h} 0 ${-h - 30} C80 ${-h} 110 -60 90 0 Z`} fill={i % 2 ? fill : fill2} />
        <path d={`M-40 -20 C-50 -60 -30 ${-h * 0.7} 10 ${-h * 0.8}`} fill="none" stroke="#FFFFFF" strokeWidth={3} opacity={0.12} />
      </g>
    ))}
  </g>
);

/** Pergola: two flower-wrapped posts, a beam, ivory swags and marigold ladis. */
export const Pergola: React.FC<{ beamY: number; sway: number }> = ({ beamY, sway }) => (
  <g>
    {[70, 1010].map((x) => (
      <g key={x}>
        <rect x={x - 18} y={beamY} width={36} height={1100} fill={palette.ivoryLight} />
        <rect x={x - 18} y={beamY} width={10} height={1100} fill={palette.ivoryShade} />
        {new Array(12).fill(0).map((_, i) => (
          <Flower key={i} x={x + Math.sin(i * 1.3) * 16} y={beamY + 40 + i * 70} r={15} tone={i % 3 === 0 ? "rose" : i % 3 === 1 ? "orange" : "ivory"} rot={i * 33} />
        ))}
      </g>
    ))}
    <rect x={20} y={beamY - 26} width={1040} height={30} fill={palette.ivoryLight} />
    <rect x={20} y={beamY - 26} width={1040} height={4} fill={palette.gold} />
    <rect x={20} y={beamY} width={1040} height={3} fill={palette.gold} />
    {/* ivory swags */}
    {[0, 1, 2, 3].map((i) => {
      const x0 = 30 + i * 255;
      const x1 = x0 + 255;
      const d = `M${x0} ${beamY} Q${(x0 + x1) / 2 + sway} ${beamY + 150} ${x1} ${beamY} L${x1} ${beamY - 4} Q${(x0 + x1) / 2 + sway} ${beamY + 110} ${x0} ${beamY - 4} Z`;
      return (
        <g key={i}>
          <path d={d} fill="#F8EEDC" />
          <path d={`M${x0} ${beamY} Q${(x0 + x1) / 2 + sway} ${beamY + 150} ${x1} ${beamY}`} fill="none" stroke={palette.gold} strokeWidth={2.4} />
          <GarlandSwag from={[x0 + 8, beamY + 6]} to={[x1 - 8, beamY + 6]} sag={42} r={10} seed={`lp-sw${i}`} tones={["orange", "yellow", "rose"]} />
        </g>
      );
    })}
    {[30, 285, 540, 795, 1050].map((x, i) => (
      <g key={x}>
        <circle cx={x} cy={beamY} r={12} fill={palette.maroon} stroke={palette.gold} strokeWidth={2} />
        <MarigoldStrand x={x} y={beamY + 10} length={140 + (i % 2) * 90} r={11} seed={`lp-ms${i}`} sway={sway * 0.4} />
      </g>
    ))}
  </g>
);

const VP = { x: 540, farY: 1000, nearY: 1470, farHalf: 150, nearHalf: 520 };
const halfAt = (y: number) => VP.farHalf + ((VP.nearHalf - VP.farHalf) * (y - VP.farY)) / (VP.nearY - VP.farY);

/** Table rows by depth: y and scale. */
const ROWS: [number, number][] = [
  [1034, 0.3],
  [1090, 0.4],
  [1170, 0.54],
  [1280, 0.74],
  [1420, 1],
];

/** Banquet table top (far → near), thalis, runner, diyas. `t` in seconds drives the flames. */
export const BanquetTable: React.FC<{ t: number }> = ({ t }) => {
  const { x: cx, farY, nearY, farHalf, nearHalf } = VP;
  return (
    <g>
      {/* table top */}
      <path d={`M${cx - farHalf} ${farY} L${cx + farHalf} ${farY} L${cx + nearHalf} ${nearY} L${cx - nearHalf} ${nearY} Z`} fill="#FBF4E6" />
      <path d={`M${cx - farHalf} ${farY} L${cx - nearHalf} ${nearY}`} stroke={palette.gold} strokeWidth={2} />
      <path d={`M${cx + farHalf} ${farY} L${cx + nearHalf} ${nearY}`} stroke={palette.gold} strokeWidth={2} />
      {/* far edge skirt */}
      <rect x={cx - farHalf} y={farY - 1} width={farHalf * 2} height={16} fill="#EFE3CB" />
      {/* runner */}
      <path d={`M${cx - 22} ${farY} L${cx + 22} ${farY} L${cx + 92} ${nearY} L${cx - 92} ${nearY} Z`} fill={palette.maroon} />
      <path d={`M${cx - 22} ${farY} L${cx + 22} ${farY} L${cx + 92} ${nearY} L${cx - 92} ${nearY} Z`} fill="url(#brocade-gold)" opacity={0.55} />
      <path d={`M${cx - 18} ${farY} L${cx - 84} ${nearY}`} stroke={palette.goldLight} strokeWidth={2} />
      <path d={`M${cx + 18} ${farY} L${cx + 84} ${nearY}`} stroke={palette.goldLight} strokeWidth={2} />
      {/* place settings, far to near */}
      {ROWS.map(([y, s], i) => {
        const off = halfAt(y) * 0.62;
        return (
          <g key={i}>
            {[-1, 1].map((k) => (
              <g key={k}>
                <Thali x={cx + k * off} y={y} r={92 * s} tilt={0.36} />
                <rect x={cx + k * off + k * 110 * s - 3 * s} y={y - 14 * s} width={6 * s} height={28 * s} rx={3 * s} fill="#C9A660" transform={`rotate(${k * 12} ${cx + k * off + k * 110 * s} ${y})`} />
              </g>
            ))}
            <FlowerHeap x={cx} y={y - 6 * s} w={150 * s} r={16 * s} seed={`lt-fh${i}`} rows={2} tones={["rose", "ivory", "orange", "rose", "yellow"]} />
            {[-1, 1].map((k) => (
              <g key={`d${k}`} transform={`translate(${cx + k * 56 * s - 30 * s} ${y - 58 * s}) scale(${s})`}>
                <Diya size={60} flicker={t * 3 + i + k} />
              </g>
            ))}
          </g>
        );
      })}
    </g>
  );
};

/** Pleated front drop of the tablecloth with gold swags — the title sits on it. */
export const TableSkirt: React.FC<{ y: number }> = ({ y }) => {
  const { x: cx, nearHalf } = VP;
  const x0 = cx - nearHalf;
  const x1 = cx + nearHalf;
  return (
    <g>
      <rect x={x0} y={y} width={x1 - x0} height={1920 - y + 20} fill="#F6ECD9" />
      {new Array(18).fill(0).map((_, i) => (
        <rect key={i} x={x0 + 20 + i * 58} y={y + 70} width={3} height={1920 - y} fill="#000" opacity={0.035} />
      ))}
      <rect x={x0} y={y} width={x1 - x0} height={8} fill={palette.maroon} />
      <rect x={x0} y={y + 8} width={x1 - x0} height={3} fill={palette.gold} />
      {[0, 1, 2, 3, 4].map((i) => {
        const a = x0 + (i * (x1 - x0)) / 5;
        const b = x0 + ((i + 1) * (x1 - x0)) / 5;
        return (
          <g key={i}>
            <path d={`M${a} ${y + 12} Q${(a + b) / 2} ${y + 80} ${b} ${y + 12}`} fill="none" stroke={palette.gold} strokeWidth={2} />
            <circle cx={b} cy={y + 14} r={7} fill="url(#foil)" />
          </g>
        );
      })}
      <Leaf x={x0 - 10} y={y + 10} rot={200} s={2} />
      <Flower x={x0 + 6} y={y + 10} r={22} tone="rose" />
      <Flower x={x1 - 6} y={y + 10} r={22} tone="orange" />
    </g>
  );
};
